// The torch op layer: validate the tensor, take the plan and the window from the group, then
// barrier, transfer, barrier, copy out.
//
// The group owns everything that survives a call -- windows, plans, staging buffers -- so the
// Python side is a constructor and two forwards.
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>
#include <optional>
#include <torch/csrc/autograd/custom_function.h>
#include <torch/extension.h>
#include <torch/library.h>

#include <map>
#include <string>
#include <tuple>

#include <fast_ulysses/common.hpp>
#include <fast_ulysses/group.hpp>
#include <fast_ulysses/nvlink.hpp>
#include <fast_ulysses/transfer.hpp>
#include <fast_ulysses/work.hpp>

namespace ulysses {

namespace {

// Before any CUDAGuard: constructing one from a CPU tensor aborts inside c10 with a message that
// names neither this library nor the argument. docs/api.md promises this wording.
void require_cuda(const at::Tensor& input)
{
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor, got one on ", input.device());
}

// The windows live on one device and the barrier kernel dereferences their flag pointers, so a
// tensor from another device would launch that kernel on the wrong one. Per-tensor, so it stays out
// of the plan cache key.
void require_group_device(const UlyssesGroup& group, const at::Tensor& input)
{
    // static_cast: c10::DeviceIndex is int8_t, so streaming it prints a CHARACTER. Device 0 is a
    // NUL, which truncates the rest of the message.
    TORCH_CHECK(input.device().index() == group.device_index(),
                "input is on cuda:",
                static_cast<int64_t>(input.device().index()),
                " but this UlyssesGroup was built for cuda:",
                group.device_index(),
                "; one group serves exactly one device");
}

// vmap has no batching rule for these ops, so it falls back to a for-loop and turns one call into
// one per batch element -- silently. For a collective that is the failure this library documents
// most loudly: ranks whose batch sizes differ then issue different NUMBERS of collectives and
// hang, with nothing raised and nothing timed out. The loop is also wrong for the ops that
// allocate, since each iteration would rendezvous.
//
// One boxed kernel serves every op in the table; it only ever throws. Boxed because
// torch::CppFunction has no makeError().
void refuse_vmap(const c10::OperatorHandle& op, c10::Stack*)
{
    TORCH_CHECK(false,
                op.schema().operator_name().name,
                " does not support torch.vmap: it is a collective, and vmap would run it once "
                "per batch element -- ranks that disagree on the batch size would then hang. "
                "Call it once, outside vmap, on the full tensor. Reached from "
                "torch.autograd.grad(is_grads_batched=True) too, which batches the backward "
                "through the same for-loop.");
}

// Byte intervals [a, a+a_bytes) and [b, b+b_bytes) intersect.
bool intervals_overlap(const void* a, int64_t a_bytes, const void* b, int64_t b_bytes)
{
    const auto* pa = static_cast<const char*>(a);
    const auto* pb = static_cast<const char*>(b);
    return pa < pb + b_bytes && pb < pa + a_bytes;
}

// The validated input, the destination, the window the transfer fills, and whether those last two
// are the same buffer.
struct Call {
    at::Tensor     x;
    at::Tensor     output;
    const A2APlan* plan          = nullptr;
    const Window*  win           = nullptr;
    bool           out_is_window = false;
};

// Everything here runs BEFORE the call's first barrier, so a rejected argument leaves no rank
// waiting on peers that did not reject it.
Call prepare(const c10::intrusive_ptr<UlyssesGroup>&    group,
             const at::Tensor&                          input,
             int64_t                                    mode,
             const std::optional<std::vector<int64_t>>& seq_splits,
             const std::optional<std::vector<int64_t>>& head_splits,
             const std::optional<at::Tensor>&           out,
             WindowRole                                 role,
             bool                                       lend)
{
    Call call;
    // Here rather than deeper in: window() and make_output() also check, but the zero-copy path
    // reaches neither, and by the time anything else would notice the opening barrier has already
    // been issued -- so the rank that noticed would be waiting on peers instead of throwing.
    group->check_alive();
    // Released buffers go back to the allocator here, before this call takes any Window& out of
    // owned_. make_output() is the only other place that can prune, so a caller who takes one
    // buffer from empty_output() and drops it would otherwise pin it until destroy().
    group->prune_owned();
    require_cuda(input);
    require_group_device(*group, input);
    call.x    = input.contiguous();
    call.plan = &group->plan(call.x.sizes(), mode, call.x.scalar_type(), seq_splits, head_splits);

    if (out.has_value()) {
        call.output = *out;
        TORCH_CHECK(call.output.is_cuda() && call.output.is_contiguous(), "out must be a contiguous CUDA tensor");
        TORCH_CHECK(call.output.device().index() == group->device_index(),
                    "out is on cuda:",
                    static_cast<int64_t>(call.output.device().index()),
                    " but this UlyssesGroup was built for cuda:",
                    group->device_index());
        TORCH_CHECK(call.output.scalar_type() == call.x.scalar_type(),
                    "out has dtype ",
                    call.output.scalar_type(),
                    ", expected ",
                    call.x.scalar_type());
        TORCH_CHECK(call.output.sizes() == at::IntArrayRef(call.plan->output_shape),
                    "out has shape ",
                    call.output.sizes(),
                    ", expected ",
                    at::IntArrayRef(call.plan->output_shape));
        // A buffer from empty_output() IS a window, and the peers write it directly. Compared in
        // BYTES: a window is found by address, so the dtype it was allocated for need not be this
        // call's, and comparing the two element counts would admit a buffer too small to hold what
        // the peers are about to write into it.
        const Window* owned = group->window_of(call.output);
        if (owned != nullptr && owned->tensor.nbytes() >= call.plan->window_numel * call.x.element_size()) {
            call.win           = owned;
            call.out_is_window = true;
        }
    }
    else if (lend) {
        // No `out`, but the caller accepts a lent window: the peers write it directly and the
        // result IS that window, so there is no copy-out and the caller owns no buffer. Which
        // window is a rotation the group drives, not a choice this call makes -- see lend_window().
        const Window& lent = group->lend_window(call.x.scalar_type(), call.plan->window_numel);
        call.win           = &lent;
        call.out_is_window = true;
        call.output =
            lent.tensor.narrow(0, 0, c10::multiply_integers(call.plan->output_shape)).view(call.plan->output_shape);
    }
    else {
        call.output = at::empty(call.plan->output_shape, call.x.options());
    }

    if (call.win == nullptr) {
        call.win = &group->window(role, call.x.scalar_type(), call.plan->window_numel);
    }

    // Refuse a call whose input, or whose `out`, shares bytes with the window it is about to fill
    // -- it would be read while every peer writes it. `out` BEING the window is the zero-copy path
    // and the one legitimate case. Intervals, not a pointer comparison, because an overlap can
    // start past the window's base. The window's OWN byte size, for the reason above.
    const void*   base  = reinterpret_cast<const void*>(call.win->peer_ptrs[group->rank()]);
    const int64_t bytes = call.win->tensor.nbytes();
    TORCH_CHECK(!intervals_overlap(call.x.data_ptr(), call.x.nbytes(), base, bytes),
                "input overlaps the window this call fills: it would be read while every peer "
                "writes it. Pass a separate output buffer, or let the call allocate one.");
    if (!call.out_is_window) {
        TORCH_CHECK(!intervals_overlap(call.output.data_ptr(), call.output.nbytes(), base, bytes),
                    "out overlaps the window this call fills without being it, which neither "
                    "writes correctly nor copies out correctly. Pass a whole buffer from "
                    "group.empty_output(), or one outside symmetric memory.");
    }
    return call;
}

// Records the staging release on scope exit, INCLUDING when the transfer throws. Without it a
// throw after the copies were issued leaves the release event unrecorded, and the next call for
// that shape overwrites the staging buffer while the comm stream is still reading it -- silently,
// because waiting on an unrecorded event succeeds and does nothing.
struct StagingRelease {
    UlyssesGroup*          group;
    UlyssesGroup::Staging* slot;
    cudaStream_t           comm;

    ~StagingRelease()
    {
        // The slot this call used, not "the last one staged": several calls of one shape can be in
        // flight, and each has to release its own.
        group->release_staging(slot, comm);  // noexcept; see the header
    }
};

// Barrier, transfer, barrier: everything the call does to the window, ordered on `stream`.
void transfer_on_stream(const c10::intrusive_ptr<UlyssesGroup>& group, const Call& call, cudaStream_t stream)
{
    const int rank = static_cast<int>(group->rank());

    // WRITERS WAIT FOR READERS, before writing anything. The window is single-buffered, so this
    // call is about to overwrite what the previous one produced, which a peer may still be
    // reading; the closing barrier below proves everyone's WRITES landed and nothing about their
    // READS. It guards the START of a call rather than the end of the previous one because on the
    // zero-copy path the result is read by the caller at a time the operator never sees.
    fast_barrier(stream, call.win->flag_ptrs, rank);

    launch_a2a_ce(call.x.data_ptr(), call.win->peer_ptrs, *call.plan, group->xfer_stream(), rank, stream);

    // That a completed peer memcpy is VISIBLE at the destination when this kernel's release store
    // arrives is an ASSUMPTION, not a documented guarantee -- test/distributed/ce_ordering.py is
    // the negative control for it.
    fast_barrier(stream, call.win->flag_ptrs, rank);
}

// Window -> the caller's tensor, ordered after the closing barrier on the same stream. Every
// rank's result is dense from the window base, so this is one flat device-to-device copy -- this
// rank's own share included, since it travels through the window like every peer's.
void copy_out(const Call& call, cudaStream_t stream, int rank)
{
    ULYSSES_CUDA_CHECK(cudaMemcpyAsync(call.output.data_ptr(),
                                       reinterpret_cast<const void*>(call.win->peer_ptrs[rank]),
                                       static_cast<size_t>(call.output.nbytes()),
                                       cudaMemcpyDeviceToDevice,
                                       stream));
}

at::Tensor run(const c10::intrusive_ptr<UlyssesGroup>&    group,
               const at::Tensor&                          input,
               int64_t                                    mode,
               const std::optional<std::vector<int64_t>>& seq_splits,
               const std::optional<std::vector<int64_t>>& head_splits,
               const std::optional<at::Tensor>&           out,
               WindowRole                                 role,
               cudaStream_t                               stream,
               bool                                       lend)
{
    const Call call = prepare(group, input, mode, seq_splits, head_splits, out, role, lend);
    transfer_on_stream(group, call, stream);
    if (!call.out_is_window) {
        copy_out(call, stream, static_cast<int>(group->rank()));
    }
    return call.output;
}

}  // namespace

// The one collective, in two forms.
//
// They are two ops rather than one with an optional `out` because a single op cannot be both
// honest and differentiable. Declaring the alias `out` really has -- Tensor(a!) -- makes the
// schema mutable, and torch/library.py refuses to register an autograd formula for a mutable
// operator. Splitting gives the functional form autograd and a meta kernel, and gives the
// out-variant an annotation that matches what it does. `-> ()` rather than `-> Tensor(a!)`
// because can_auto_functionalize accepts only that shape, so only that shape can enter a graph.
at::Tensor all_to_all_4d(const c10::intrusive_ptr<UlyssesGroup>&    group,
                         const at::Tensor&                          input,
                         int64_t                                    mode,
                         const std::optional<std::vector<int64_t>>& seq_splits,
                         const std::optional<std::vector<int64_t>>& head_splits)
{
    require_cuda(input);
    const at::cuda::CUDAGuard guard(input.device());
    return run(group,
               input,
               mode,
               seq_splits,
               head_splits,
               std::nullopt,
               kSyncWindow,
               at::cuda::getCurrentCUDAStream(),
               /*lend=*/false);
}

// Shape propagation for FakeTensor and AOTAutograd. CompositeExplicitAutograd already covers the
// Meta key, so without this a fake tensor reaches the real kernel and dies on require_cuda -- a
// message about a CUDA tensor, for what is really an untraceable-op problem. A direct Meta
// registration takes precedence over the alias.
//
// The arithmetic stays in group->plan(): it is pure host code that allocates nothing on the device,
// so it is safe here, and it runs every shape, dtype and splits check on the way. Rewriting the
// uneven-splits rule in Python would put a second copy of it somewhere test_plan.py cannot reach --
// which is the whole reason a2a_plan.cc is a torch-free, CUDA-free translation unit.
//
// The group is a real object on this path: FakeTensorMode's conversion only touches tensors, so the
// ScriptObject arrives intact and world_size is available -- which it is not from the input shape
// alone when the splits are absent.
at::Tensor all_to_all_4d_meta(const c10::intrusive_ptr<UlyssesGroup>&    group,
                              const at::Tensor&                          input,
                              int64_t                                    mode,
                              const std::optional<std::vector<int64_t>>& seq_splits,
                              const std::optional<std::vector<int64_t>>& head_splits)
{
    const A2APlan& plan = group->plan(input.sizes(), mode, input.scalar_type(), seq_splits, head_splits);
    return at::empty(plan.output_shape, input.options());
}

// empty_output is a COLLECTIVE allocation, so it cannot be traced at all: replaying a trace would
// put the rendezvous wherever the graph happens to place it rather than where every rank's own
// program reaches it. Say that, instead of letting it fall through to a CUDA-tensor complaint.
at::Tensor empty_output_meta(const c10::intrusive_ptr<UlyssesGroup>&,
                             const at::Tensor&,
                             int64_t,
                             const std::optional<std::vector<int64_t>>&,
                             const std::optional<std::vector<int64_t>>&)
{
    TORCH_CHECK(false,
                "empty_output is a collective allocation and cannot be traced: every rank has to "
                "reach it at the same point in its own program. Call it eagerly, outside the "
                "region being traced, and pass the buffer in.");
}

// Fills `out`. A buffer from empty_output() IS the window, so the peers write it directly and the
// copy-out disappears; any other contiguous tensor of the output shape is copied into.
void all_to_all_4d_out(const c10::intrusive_ptr<UlyssesGroup>&    group,
                       const at::Tensor&                          input,
                       int64_t                                    mode,
                       const std::optional<std::vector<int64_t>>& seq_splits,
                       const std::optional<std::vector<int64_t>>& head_splits,
                       const at::Tensor&                          out)
{
    require_cuda(input);
    const at::cuda::CUDAGuard guard(input.device());
    run(group,
        input,
        mode,
        seq_splits,
        head_splits,
        out,
        kSyncWindow,
        at::cuda::getCurrentCUDAStream(),
        /*lend=*/false);
}

// The out-variant's share of the shape rule. Without it a fake tensor reaches the real kernel and
// dies on require_cuda -- the misleading message all_to_all_4d_meta exists to prevent -- on the very
// variant the schema split was made for, since `-> ()` is the only shape can_auto_functionalize
// accepts. Nothing to return: the caller's buffer is the result and its shape is checked, not
// derived.
void all_to_all_4d_out_meta(const c10::intrusive_ptr<UlyssesGroup>&    group,
                            const at::Tensor&                          input,
                            int64_t                                    mode,
                            const std::optional<std::vector<int64_t>>& seq_splits,
                            const std::optional<std::vector<int64_t>>& head_splits,
                            const at::Tensor&                          out)
{
    const A2APlan& plan = group->plan(input.sizes(), mode, input.scalar_type(), seq_splits, head_splits);
    TORCH_CHECK(out.scalar_type() == input.scalar_type(),
                "out has dtype ",
                out.scalar_type(),
                ", expected ",
                input.scalar_type());
    TORCH_CHECK(out.sizes() == at::IntArrayRef(plan.output_shape),
                "out has shape ",
                out.sizes(),
                ", expected ",
                at::IntArrayRef(plan.output_shape));
}

// The async form's device-side half. Python has already made the comm stream current; `caller` is
// the stream the user was on, which is where the input is staged.
//
// Everything both staged forms share, so the split above costs one wrapper rather than a
// duplicated body.
namespace {

at::Tensor run_staged(const c10::intrusive_ptr<UlyssesGroup>&    group,
                      const at::Tensor&                          input,
                      int64_t                                    mode,
                      const std::optional<std::vector<int64_t>>& seq_splits,
                      const std::optional<std::vector<int64_t>>& head_splits,
                      const std::optional<at::Tensor>&           out,
                      int64_t                                    caller_stream_id,
                      int64_t                                    caller_device_index,
                      bool                                       lend)
{
    // Both before stage(), unlike every other check, which prepare() runs. destroy() returns early
    // the second time, so a staging entry created after it is never freed and its event leaks with
    // the group. And the staging buffer takes the INPUT's device while being cached by shape and
    // dtype alone, so one wrong-device call would leave a buffer on that device behind and every
    // later call for that shape would copy across devices before failing this same check. The comm
    // stream below is read through the current device too, which a guard on the wrong one moves.
    group->check_alive();
    require_cuda(input);
    require_group_device(*group, input);
    const at::cuda::CUDAGuard guard(input.device());
    cudaStream_t              comm = at::cuda::getCurrentCUDAStream();
    // Rebuilt from torch's own identifiers rather than wrapped from a raw handle, so the caching
    // allocator sees the same stream object the caller was using.
    const c10::cuda::CUDAStream caller(c10::Stream::unpack3(
        caller_stream_id, static_cast<c10::DeviceIndex>(caller_device_index), c10::DeviceType::CUDA));
    // Stage on the caller's stream, so the caller's tensor is never read by the comm stream --
    // record_stream would instead pin every freed input until the comm stream caught up. The
    // staging copy also absorbs a strided input, which is why nothing calls contiguous() here:
    // doing so would launch that copy on the comm stream, which is exactly what this avoids.
    UlyssesGroup::Staging* slot = group->stage(input, caller, comm);
    const StagingRelease   release{group.get(), slot, comm};
    return run(group, slot->tensor, mode, seq_splits, head_splits, out, kAsyncWindow, comm, lend);
}

}  // namespace

at::Tensor all_to_all_4d_staged(const c10::intrusive_ptr<UlyssesGroup>&    group,
                                const at::Tensor&                          input,
                                int64_t                                    mode,
                                const std::optional<std::vector<int64_t>>& seq_splits,
                                const std::optional<std::vector<int64_t>>& head_splits,
                                int64_t                                    caller_stream_id,
                                int64_t                                    caller_device_index,
                                bool                                       lend)
{
    return run_staged(
        group, input, mode, seq_splits, head_splits, std::nullopt, caller_stream_id, caller_device_index, lend);
}

void all_to_all_4d_staged_out(const c10::intrusive_ptr<UlyssesGroup>&    group,
                              const at::Tensor&                          input,
                              int64_t                                    mode,
                              const std::optional<std::vector<int64_t>>& seq_splits,
                              const std::optional<std::vector<int64_t>>& head_splits,
                              const at::Tensor&                          out,
                              int64_t                                    caller_stream_id,
                              int64_t                                    caller_device_index)
{
    run_staged(group, input, mode, seq_splits, head_splits, out, caller_stream_id, caller_device_index, /*lend=*/false);
}

// The staged pair REFUSES to be traced, the way empty_output does, rather than propagating a
// shape it could perfectly well compute.
//
// Returning a shape here is not half an answer, it is a wrong one, because this op is only ever
// reached through all_to_all_4d_async and the Python around it is eager-only. Let the op return
// and that wrapper goes on to record a completion event on the comm stream and hand it to torch's
// work registry, then call record_stream on the result: a traced call therefore leaves a real
// Work in a process-global registry that nothing will ever wait on, and returns an
// AsyncCollectiveTensor whose wait() claims a transfer that was never issued. The arguments say
// the same thing -- caller_stream_id and caller_device_index name a live CUDA stream, and a graph
// that has one baked into it is wrong everywhere it is replayed.
//
// The shape half is available from all_to_all_4d, which moves exactly the same bytes.
at::Tensor all_to_all_4d_staged_meta(const c10::intrusive_ptr<UlyssesGroup>&,
                                     const at::Tensor&,
                                     int64_t,
                                     const std::optional<std::vector<int64_t>>&,
                                     const std::optional<std::vector<int64_t>>&,
                                     int64_t,
                                     int64_t,
                                     bool)
{
    TORCH_CHECK(false,
                "all_to_all_4d_async cannot be traced: it completes through a CUDA event bound to "
                "torch's work registry and takes the caller's stream as an argument, neither of "
                "which a traced call has. Trace all_to_all_4d instead, which moves the same bytes.");
}

// Same refusal, same reason: the out-variant's completion is registered against `out`.
void all_to_all_4d_staged_out_meta(const c10::intrusive_ptr<UlyssesGroup>&,
                                   const at::Tensor&,
                                   int64_t,
                                   const std::optional<std::vector<int64_t>>&,
                                   const std::optional<std::vector<int64_t>>&,
                                   const at::Tensor&,
                                   int64_t,
                                   int64_t)
{
    TORCH_CHECK(false,
                "all_to_all_4d_async cannot be traced: it completes through a CUDA event bound to "
                "torch's work registry and takes the caller's stream as an argument, neither of "
                "which a traced call has. Trace all_to_all_4d(out=...) instead, which moves the "
                "same bytes.");
}

// Re-enter the DISPATCHER with the autograd keys excluded.
//
// Not a direct call to all_to_all_4d(): that would leave dispatch for good, and every key below
// Autograd -- Python, and through it FakeTensorMode, and Meta -- would never be consulted, so a
// fake tensor would reach the real kernel and die in cudaMemcpy3DAsync.
//
// The guard is what stops op.call from arriving back at the Autograd kernel. GradMode being off
// is not enough: it governs graph construction, not which kernel the dispatcher picks.
at::Tensor dispatch_below_autograd(const c10::intrusive_ptr<UlyssesGroup>&    group,
                                   const at::Tensor&                          input,
                                   int64_t                                    mode,
                                   const std::optional<std::vector<int64_t>>& seq_splits,
                                   const std::optional<std::vector<int64_t>>& head_splits)
{
    at::AutoDispatchBelowADInplaceOrView guard;
    static auto                          op = c10::Dispatcher::singleton()
                         .findSchemaOrThrow("fast_ulysses::all_to_all_4d", "")
                         .typed<at::Tensor(const c10::intrusive_ptr<UlyssesGroup>&,
                                           const at::Tensor&,
                                           int64_t,
                                           const std::optional<std::vector<int64_t>>&,
                                           const std::optional<std::vector<int64_t>>&)>();
    return op.call(group, input, mode, seq_splits, head_splits);
}

// The adjoint of the collective is the collective in the other direction.
//
// mode 0 is a bijection on the global element set -- rank r's (batch, s, n, k) lands at rank
// owner(n) position (batch, seq_offset[r]+s, n-head_offset[p], k) -- and mode 1 with the SAME
// splits is `build_plan`'s scatter branch read right to left, i.e. its inverse. The Jacobian of a
// permutation is a permutation matrix, whose transpose is its inverse, so the vjp is `1 - mode`.
//
// The splits do NOT swap. That is worth stating because all_to_all_single's backward DOES swap its
// input and output split sizes: those describe one call's send and receive counts, so reversing the
// direction reverses their roles. seq_splits[p] / head_splits[p] are a different object -- rank p's
// sequence and head shard, a property of the GROUP that holds whichever way the data moves. `mode`
// selects which axis arrives already sharded, not what the lists mean. test_plan.py's round trip
// builds both plans from one pair of genuinely uneven lists and confirms it numerically.
//
// Absent splits pass through too: mode 0 with none derives seq=[x1]*ws, head=[x2/ws]*ws, and mode 1
// with none on that output shape derives the same pair -- and can never fail a divisibility check
// the forward did not already pass, since the axis it tests is ws times something.
class A2AFunction: public torch::autograd::Function<A2AFunction> {
public:
    static at::Tensor forward(torch::autograd::AutogradContext*          ctx,
                              const c10::intrusive_ptr<UlyssesGroup>&    group,
                              const at::Tensor&                          input,
                              int64_t                                    mode,
                              const std::optional<std::vector<int64_t>>& seq_splits,
                              const std::optional<std::vector<int64_t>>& head_splits)
    {
        // The graph holds the group alive. A graph that outlives destroy() raises from backward,
        // which is the right answer -- there is nothing left to run the collective on.
        ctx->saved_data["group"] = group;
        ctx->saved_data["mode"]  = mode;
        ctx->saved_data["seq"]   = seq_splits.has_value() ? c10::IValue(*seq_splits) : c10::IValue();
        ctx->saved_data["head"]  = head_splits.has_value() ? c10::IValue(*head_splits) : c10::IValue();

        return dispatch_below_autograd(group, input, mode, seq_splits, head_splits);
    }

    static torch::autograd::variable_list backward(torch::autograd::AutogradContext* ctx,
                                                   torch::autograd::variable_list    grads)
    {
        // Five entries, one per non-ctx forward argument; only `input` is differentiable.
        if (!grads[0].defined()) {
            return {at::Tensor(), at::Tensor(), at::Tensor(), at::Tensor(), at::Tensor()};
        }
        auto          group = ctx->saved_data["group"].toCustomClass<UlyssesGroup>();
        const int64_t mode  = ctx->saved_data["mode"].toInt();

        std::optional<std::vector<int64_t>> seq, head;
        if (!ctx->saved_data["seq"].isNone()) {
            seq = ctx->saved_data["seq"].toIntVector();
        }
        if (!ctx->saved_data["head"].isNone()) {
            head = ctx->saved_data["head"].toIntVector();
        }

        // The copying form, never `out` from empty_output(): that is a collective allocation, and
        // putting one inside backward would hand the rendezvous position to the autograd engine's
        // node order rather than to the caller's own program. A gradient also belongs to the
        // engine, which may accumulate into it or hold it, while a window is single-buffered.
        //
        // apply(), not the plain function, so grad-of-grad routes back through here.
        return {at::Tensor(),
                A2AFunction::apply(group, grads[0].contiguous(), 1 - mode, seq, head),
                at::Tensor(),
                at::Tensor(),
                at::Tensor()};
    }
};

namespace {

// The node apply() allocates is dead weight when nothing will use it, and this operator runs twice
// per attention layer per step.
at::Tensor with_reverse_ad(const c10::intrusive_ptr<UlyssesGroup>&    group,
                           const at::Tensor&                          input,
                           int64_t                                    mode,
                           const std::optional<std::vector<int64_t>>& seq_splits,
                           const std::optional<std::vector<int64_t>>& head_splits)
{
    if (!at::GradMode::is_enabled() || !input.requires_grad()) {
        return dispatch_below_autograd(group, input, mode, seq_splits, head_splits);
    }
    return A2AFunction::apply(group, input, mode, seq_splits, head_splits);
}

// The only forward-AD level torch has.
constexpr uint64_t kFwLevel = 0;

}  // namespace

at::Tensor all_to_all_4d_autograd(const c10::intrusive_ptr<UlyssesGroup>&    group,
                                  const at::Tensor&                          input,
                                  int64_t                                    mode,
                                  const std::optional<std::vector<int64_t>>& seq_splits,
                                  const std::optional<std::vector<int64_t>>& head_splits)
{
    // Forward mode is handled HERE, not in A2AFunction: torch::autograd::Function has no jvp hook
    // in C++, so a dual input reaching apply() raises, and one taking with_reverse_ad's fast path
    // would have its tangent dropped without a word. The jvp of a permutation is the permutation, so
    // the tangent goes through the same call -- one more collective, which every rank issues,
    // because every rank runs this graph.
    const at::Tensor tangent = input._fw_grad(kFwLevel);
    if (!tangent.defined()) {
        return with_reverse_ad(group, input, mode, seq_splits, head_splits);
    }
    // The primal keeps the reverse-mode history and carries no tangent, so apply() may see it.
    at::Tensor result = with_reverse_ad(group, input._fw_primal(kFwLevel), mode, seq_splits, head_splits);
    result._set_fw_grad(with_reverse_ad(group, tangent, mode, seq_splits, head_splits),
                        kFwLevel,
                        /*is_inplace_op=*/false);
    return result;
}

// A buffer shaped like this call's output, in symmetric memory, for the caller to pass back as
// `out`. COLLECTIVE.
at::Tensor empty_output(const c10::intrusive_ptr<UlyssesGroup>&    group,
                        const at::Tensor&                          input,
                        int64_t                                    mode,
                        const std::optional<std::vector<int64_t>>& seq_splits,
                        const std::optional<std::vector<int64_t>>& head_splits)
{
    require_cuda(input);
    const at::cuda::CUDAGuard guard(input.device());
    const A2APlan&            plan = group->plan(input.sizes(), mode, input.scalar_type(), seq_splits, head_splits);
    return group->make_output(plan.output_shape, input.scalar_type(), plan.window_numel);
}

// Benchmark-only: the copying call with CUDA events between its stages, strictly ordered on one
// stream so they sum to the whole call. `transfer` covers the peer copies plus this rank's own
// share, which runs on the caller's stream underneath them and so cannot be timed apart.
std::tuple<at::Tensor, std::vector<double>> all_to_all_4d_timed(const c10::intrusive_ptr<UlyssesGroup>&    group,
                                                                const at::Tensor&                          input,
                                                                int64_t                                    mode,
                                                                const std::optional<std::vector<int64_t>>& seq_splits,
                                                                const std::optional<std::vector<int64_t>>& head_splits)
{
    require_cuda(input);
    const at::cuda::CUDAGuard guard(input.device());
    const Call   call = prepare(group, input, mode, seq_splits, head_splits, std::nullopt, kSyncWindow, /*lend=*/false);
    const int    rank = static_cast<int>(group->rank());
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    // Default flags, not cudaEventDisableTiming: cudaEventElapsedTime below needs the timestamps.
    const Event marks[5];
    ULYSSES_CUDA_CHECK(cudaEventRecord(marks[0], stream));
    fast_barrier(stream, call.win->flag_ptrs, rank);
    ULYSSES_CUDA_CHECK(cudaEventRecord(marks[1], stream));
    launch_a2a_ce(call.x.data_ptr(), call.win->peer_ptrs, *call.plan, group->xfer_stream(), rank, stream);
    ULYSSES_CUDA_CHECK(cudaEventRecord(marks[2], stream));
    fast_barrier(stream, call.win->flag_ptrs, rank);
    ULYSSES_CUDA_CHECK(cudaEventRecord(marks[3], stream));
    copy_out(call, stream, rank);
    ULYSSES_CUDA_CHECK(cudaEventRecord(marks[4], stream));

    ULYSSES_CUDA_CHECK(cudaEventSynchronize(marks[4]));
    std::vector<double> stages(4, 0.0);
    for (int i = 0; i < 4; ++i) {
        float ms = 0.0F;
        ULYSSES_CUDA_CHECK(cudaEventElapsedTime(&ms, marks[i], marks[i + 1]));
        stages[i] = static_cast<double>(ms);
    }
    return {call.output, stages};
}

// Refuses, like empty_output's, rather than returning the shape with four zeros.
//
// Half of what this op returns is a measurement, and a traced call performs nothing to measure. A
// zeroed vector is not a missing answer, it is a wrong one: whoever reads it gets four durations
// with the units and the shape of real ones, and a benchmark that averages them reports a call
// that took no time. The shape half is available from all_to_all_4d, which is the same collective;
// this op exists only to time it, and timing wants the eager call.
std::tuple<at::Tensor, std::vector<double>> all_to_all_4d_timed_meta(const c10::intrusive_ptr<UlyssesGroup>&,
                                                                     const at::Tensor&,
                                                                     int64_t,
                                                                     const std::optional<std::vector<int64_t>>&,
                                                                     const std::optional<std::vector<int64_t>>&)
{
    TORCH_CHECK(false,
                "all_to_all_4d_timed cannot be traced: it returns CUDA event timings, and a traced "
                "call runs nothing to time. Call it eagerly, or trace all_to_all_4d instead.");
}

}  // namespace ulysses

TORCH_LIBRARY(fast_ulysses, m)
{
    m.class_<ulysses::UlyssesGroup>("UlyssesGroup")
        .def(torch::init<std::string, int64_t, int64_t, int64_t>())
        .def("destroy", &ulysses::UlyssesGroup::destroy)
        // TESTS ONLY, and a method rather than a pybind function because the group is a torchbind
        // object, which pybind cannot take. test/distributed/cudagraph.py needs it: torn data is a
        // SUFFICIENT signal that the handshake died, not a necessary one -- a replay where no peer
        // happened to be late comes back clean either way, and only the epoch says whether the
        // barrier was alive. Synchronising; `like` carries the dtype that keys the window.
        .def("epoch_debug",
             [](const c10::intrusive_ptr<ulysses::UlyssesGroup>& self, const at::Tensor& probe, int64_t role) {
                 return self->epoch(probe, static_cast<ulysses::WindowRole>(role));
             })
        // TESTS ONLY, same reason. test/distributed/correctness.py needs it: several same-shaped
        // async calls in flight at once is what the staging pool exists for, and the results
        // cannot show it -- sharing one slot is CORRECT, it only serialises the calls on the
        // caller's stream. The slot count separates the two. `like` carries the (shape, dtype).
        .def("staging_slots_debug", [](const c10::intrusive_ptr<ulysses::UlyssesGroup>& self, const at::Tensor& like) {
            return self->staging_slots(like);
        });

    // BOTH batching keys, for every op below.
    //
    // FuncTorchBatched is the one torch.vmap uses, and it wins over an op's Autograd kernel, so it
    // also covers a vmap over a grad-requiring input and a nested vmap. Batched is the LEGACY
    // vmap's key, and it is still reachable from a supported public API: torch.autograd.grad(...,
    // is_grads_batched=True) -- and torch.autograd.functional.* with vectorize=True through it --
    // goes through torch._vmap_internals, not functorch. Registering only the first leaves that
    // path looping one collective per row of the batch, which is the failure being refused.
    //
    // Neither fires when the tensor handed to the collective is a closed-over constant, which is a
    // genuinely-once call inside somebody else's vmap and stays legal.
    auto refuse_batching = [&m](const char* name) {
        for (const c10::DispatchKey key : {c10::DispatchKey::FuncTorchBatched, c10::DispatchKey::Batched}) {
            m.impl(name, key, torch::CppFunction::makeFromBoxedFunction<&ulysses::refuse_vmap>());
        }
    };

    // Functional: no alias, so it can carry an autograd formula and a meta kernel.
    m.def("all_to_all_4d(__torch__.torch.classes.fast_ulysses.UlyssesGroup group, Tensor input, "
          "int mode, int[]? seq_splits=None, int[]? head_splits=None) -> Tensor");
    m.impl("all_to_all_4d", c10::DispatchKey::CompositeExplicitAutograd, &ulysses::all_to_all_4d);
    m.impl("all_to_all_4d", c10::DispatchKey::Autograd, &ulysses::all_to_all_4d_autograd);
    // Explicit Meta, overriding the alias above. Deliberately NOT also torch.library.register_fake:
    // on 2.13 that silently replaces an existing Meta kernel, leaving two shape rules and no error
    // saying which one ran.
    m.impl("all_to_all_4d", c10::DispatchKey::Meta, &ulysses::all_to_all_4d_meta);
    refuse_batching("all_to_all_4d");

    // Mutating, and says so. Not differentiable: the gradient would have to flow back out of a
    // buffer the caller owns and may already have overwritten.
    m.def("all_to_all_4d_out(__torch__.torch.classes.fast_ulysses.UlyssesGroup group, Tensor input, "
          "int mode, int[]? seq_splits, int[]? head_splits, Tensor(a!) out) -> ()");
    m.impl("all_to_all_4d_out", c10::DispatchKey::CompositeExplicitAutograd, &ulysses::all_to_all_4d_out);
    m.impl("all_to_all_4d_out", c10::DispatchKey::Meta, &ulysses::all_to_all_4d_out_meta);
    // Registered although torch's for-loop fallback already refuses out-variants: that refusal is
    // torch's own, for its own reasons, and a torch that grew an out= batching fallback would make
    // this op start looping silently. One line makes it a property of this library instead.
    refuse_batching("all_to_all_4d_out");

    m.def("all_to_all_4d_staged(__torch__.torch.classes.fast_ulysses.UlyssesGroup group, "
          "Tensor input, int mode, int[]? seq_splits, int[]? head_splits, "
          "int caller_stream_id, int caller_device_index, bool lend=False) -> Tensor");
    m.impl("all_to_all_4d_staged", c10::DispatchKey::CompositeExplicitAutograd, &ulysses::all_to_all_4d_staged);
    m.impl("all_to_all_4d_staged", c10::DispatchKey::Meta, &ulysses::all_to_all_4d_staged_meta);
    refuse_batching("all_to_all_4d_staged");

    m.def("all_to_all_4d_staged_out(__torch__.torch.classes.fast_ulysses.UlyssesGroup group, "
          "Tensor input, int mode, int[]? seq_splits, int[]? head_splits, Tensor(a!) out, "
          "int caller_stream_id, int caller_device_index) -> ()");
    m.impl("all_to_all_4d_staged_out", c10::DispatchKey::CompositeExplicitAutograd, &ulysses::all_to_all_4d_staged_out);
    m.impl("all_to_all_4d_staged_out", c10::DispatchKey::Meta, &ulysses::all_to_all_4d_staged_out_meta);
    refuse_batching("all_to_all_4d_staged_out");

    m.def("empty_output(__torch__.torch.classes.fast_ulysses.UlyssesGroup group, Tensor input, "
          "int mode, int[]? seq_splits=None, int[]? head_splits=None) -> Tensor");
    m.impl("empty_output", c10::DispatchKey::CompositeExplicitAutograd, &ulysses::empty_output);
    m.impl("empty_output", c10::DispatchKey::Meta, &ulysses::empty_output_meta);
    // A fresh buffer has no data dependence on the tensor whose shape it was taken from, so it must
    // not inherit that tensor's requires_grad. Without this the Autograd key falls back to
    // autogradNotImplementedFallback, which builds a node over the buffer and hands back a non-leaf
    // the caller cannot even detach in place.
    m.impl("empty_output", c10::DispatchKey::Autograd, torch::CppFunction::makeFallthrough());
    // The loop would rendezvous once per batch element, which is the same hang with an extra way in.
    refuse_batching("empty_output");

    m.def("all_to_all_4d_timed(__torch__.torch.classes.fast_ulysses.UlyssesGroup group, "
          "Tensor input, int mode, int[]? seq_splits=None, int[]? head_splits=None) "
          "-> (Tensor, float[])");
    m.impl("all_to_all_4d_timed", c10::DispatchKey::CompositeExplicitAutograd, &ulysses::all_to_all_4d_timed);
    m.impl("all_to_all_4d_timed", c10::DispatchKey::Meta, &ulysses::all_to_all_4d_timed_meta);
    // Same as empty_output: it measures, it does not differentiate.
    m.impl("all_to_all_4d_timed", c10::DispatchKey::Autograd, torch::CppFunction::makeFallthrough());
    refuse_batching("all_to_all_4d_timed");
}

// Python `import _C` needs PyInit__C; TORCH_LIBRARY already registered at dlopen time.
PYBIND11_MODULE(_C, m)
{
    // The async wrapper is Python-side, so this is the one piece that has to be here: c10d::Work
    // is a C++ interface. Not a torch op -- it takes a raw stream handle and mutates a
    // process-wide registry, neither of which belongs in a schema.
    m.def("register_stream_completion", [](const at::Tensor& tensor, int64_t comm_stream) {
        return ulysses::register_stream_completion(tensor, reinterpret_cast<cudaStream_t>(comm_stream));
    });

    // {(i, j): joined by NVLink} over CUDA device indices, or None when NVML cannot say.
    m.def("nvlink_matrix", [](const std::vector<int64_t>& devices) -> py::object {
        const auto matrix = ulysses::nvlink_matrix(devices);
        if (!matrix.has_value()) {
            return py::none();
        }
        py::dict out;
        for (const auto& entry : *matrix) {
            out[py::make_tuple(entry.first.first, entry.first.second)] = py::bool_(entry.second);
        }
        return out;
    });

    // Empty when every pair is NVLink-joined, or when NVML cannot say.
    m.def("check_nvlink", &ulysses::check_nvlink);

    // TESTS ONLY. Underscored, and not a torch op, because arming it deliberately breaks the
    // operator: it is the negative control for test/distributed/ce_ordering.py.
    m.def("_set_ce_fault", &ulysses::set_ce_fault);

    m.def("build_info", []() {
        std::map<std::string, std::string> out;
        out["version"]        = FAST_ULYSSES_VERSION;
        out["cuda_arch_list"] = FAST_ULYSSES_CUDA_ARCH_LIST;
        return out;
    });
}

#pragma once
/// @file
/// The group: symmetric windows, the cached plans, and the transfer stream.
///
/// Everything a call needs on the host lives here, so the Python side is a constructor and two
/// one-line forwards. Windows are torch symmetric-memory allocations
/// (`c10d::symmetric_memory::empty_strided_p2p` + `rendezvous`), which is the same mechanism
/// torch's own `symm_mem.empty()` uses and is available unchanged from torch 2.10 on.
#include <c10/cuda/CUDAStream.h>
#include <cstdint>
#include <cuda_runtime.h>
#include <map>
#include <memory>
#include <optional>
#include <string>
#include <torch/custom_class.h>
#include <vector>

#include <fast_ulysses/a2a_plan.hpp>

namespace ulysses {

/// @brief One symmetric allocation plus the addresses the transport needs.
struct Window {
    at::Tensor            tensor;     ///< holds the allocation alive
    std::vector<uint64_t> peer_ptrs;  ///< peer p's copy of it, as addressed from here
    std::vector<uint64_t> flag_ptrs;  ///< peer p's handshake region inside its signal pad
    int64_t               numel = 0;
};

/// @brief Which stream a window belongs to. A window is single-buffered, so two calls may share
/// one only when a stream orders them -- and the sync and async calls run on different streams.
enum WindowRole : int64_t {
    kSyncWindow  = 0,
    kAsyncWindow = 1,
};

class UlyssesGroup: public torch::CustomClassHolder {
public:
    /// @param group_name  the process group's name, which is what rendezvous keys on
    UlyssesGroup(std::string group_name, int64_t rank, int64_t world_size, int64_t device_index);
    ~UlyssesGroup() override;

    int64_t rank() const
    {
        return rank_;
    }

    int64_t world_size() const
    {
        return world_size_;
    }

    /// @brief The device this group's windows live on. One group serves exactly one device.
    int64_t device_index() const
    {
        return device_index_;
    }

    /// @brief Throw if destroy() has already run.
    ///
    /// Call this BEFORE the call's first barrier. The zero-copy path reaches neither window() nor
    /// make_output(), so without an explicit check a destroyed group would run the whole collective
    /// and rebuild the transfer stream it had just torn down.
    void check_alive() const;

    /// @brief Drop the make_output() records whose buffer the caller has released, so the symmetric
    /// allocation goes back to the allocator. Never call this while a Window& taken from owned_ is
    /// still live -- it invalidates them.
    void prune_owned();

    /// @brief The plan for this call, built once per distinct (shape, mode, dtype, splits).
    ///
    /// build_plan allocates several vectors, which is a few microseconds of host time on every
    /// call; the answer only depends on the key, so it is kept.
    const A2APlan& plan(at::IntArrayRef                            sizes,
                        int64_t                                    mode,
                        at::ScalarType                             dtype,
                        const std::optional<std::vector<int64_t>>& seq_splits,
                        const std::optional<std::vector<int64_t>>& head_splits);

    /// @brief This group's window for `role`, allocated on first use and grown when a call needs
    /// more than the last one did. COLLECTIVE when it allocates.
    const Window& window(WindowRole role, at::ScalarType dtype, int64_t numel);

    /// @brief A window the caller owns, for the zero-copy path. COLLECTIVE.
    at::Tensor make_output(at::IntArrayRef shape, at::ScalarType dtype, int64_t numel);

    /// @brief A window to LEND for this call's output: the peers write it, the result IS it, and
    /// nothing is copied out. COLLECTIVE when it allocates.
    ///
    /// `out=` buys the same saving and hands the caller the lifetime with it -- one buffer per
    /// concurrent call, and never read a result after reissuing that buffer's call. Here the group
    /// keeps the buffers and rotates through a fixed set of them.
    ///
    /// THE SLOT IS CHOSEN BY A CALL COUNTER, not by looking for one that is free. Every rank has to
    /// land on the same symmetric allocation -- the transfer addresses the peers through the chosen
    /// window's peer_ptrs and the barrier through its flag_ptrs, so ranks that disagree write past
    /// each other and wait on flags nobody sets. A rank's own reference counts are not a quantity
    /// its peers share; the number of calls it has made is, because every rank issues the same
    /// sequence. Both conditions below that allocate are keyed on that counter or on `numel`, which
    /// is likewise the same everywhere.
    ///
    /// Reference counts are the CHECK rather than the choice: the slot the rotation lands on must
    /// be one no live result still refers to, and this throws when it is not. Throwing rather than
    /// falling back to a copy, since the fallback would be a local decision too.
    const Window& lend_window(at::ScalarType dtype, int64_t numel);

    /// @brief The window `out` is, or nullptr when it is an ordinary tensor.
    const Window* window_of(const at::Tensor& out) const;

    // (shape, dtype) -> staging buffer + the event saying the comm stream is done reading it.
    struct Staging {
        at::Tensor  tensor;
        cudaEvent_t release = nullptr;
    };

    /// @brief Staging buffer for the async path, so the caller's tensor is never retained
    /// cross-stream. Copies `x` into it on `caller`, then makes `comm` wait for that copy.
    ///
    /// Buffers of a shape form a pool rather than a single slot, so several async calls of the
    /// SAME shape can be in flight at once -- which is what splitting one packed exchange into
    /// per-tensor ones does. With one slot the second call's copy waits, ON THE CALLER'S STREAM,
    /// for the first exchange to retire, serialising the very compute it was issued early to
    /// overlap. Sharing a slot is still correct, just not concurrent.
    ///
    /// @return the slot used; pass it to release_staging() once the transfer has been issued.
    Staging* stage(const at::Tensor& x, c10::cuda::CUDAStream caller, cudaStream_t comm);

    /// @brief Record, on `comm`, that `slot` may be overwritten again.
    ///
    /// noexcept because it runs from a scope guard that must also fire while an exception from the
    /// transfer is propagating. Unchecked for the same reason, and it costs nothing: a checked
    /// record that failed would leave exactly the state an unchecked one does.
    void release_staging(Staging* slot, cudaStream_t comm) noexcept;

    cudaStream_t xfer_stream();

    /// @brief TESTS ONLY. This rank's barrier epoch for the window `probe` belongs to -- itself,
    /// when it came from make_output(), otherwise `role`'s window for its dtype. -1 when neither
    /// exists yet. Synchronising, and it reads a counter the barrier kernel owns: it is here so a
    /// CUDA-graph replay can be shown to advance the epoch rather than announce a stale one.
    int64_t epoch(const at::Tensor& probe, WindowRole role) const;

    /// @brief TESTS ONLY. How many staging slots exist for `like`'s (shape, dtype); 0 before the
    /// first async call of that shape. Whether two same-shaped calls got separate buffers is the
    /// whole point of the pool and is invisible in the results: sharing one corrupts only when the
    /// timing lines up, so a bit-exact pair proves nothing on its own and the count does.
    int64_t staging_slots(const at::Tensor& like) const;

    /// @brief Release the windows and the transfer stream. Buffers handed out by make_output are
    /// the caller's and are unaffected.
    void destroy();

private:
    struct PlanKey {
        std::vector<int64_t> sizes;
        // optional, not vector: an absent split list and an EMPTY one are different calls -- the
        // first is the even special case and the second is an error -- and as bare vectors they
        // are the same key, so the empty one would hit the even plan and skip its own rejection.
        std::optional<std::vector<int64_t>> seq, head;
        int64_t                             mode;
        at::ScalarType                      dtype;
        bool                                operator<(const PlanKey& o) const;
    };

    /// Allocate `numel` elements of symmetric memory, rendezvous, and clear the handshake region.
    Window allocate(int64_t numel, at::ScalarType dtype);

    std::string  group_name_;
    int          rank_, world_size_, device_index_;
    cudaStream_t xfer_      = nullptr;
    bool         destroyed_ = false;

    std::map<PlanKey, A2APlan>                           plans_;
    std::map<std::pair<int64_t, at::ScalarType>, Window> windows_;
    std::map<const void*, Window>                        owned_;  // handed to callers, by address

    // Lent output windows, per dtype: a fixed rotation, so the same call picks the same slot on
    // every rank. Four is a packed exchange split into q/k/v with one still in flight; a caller
    // holding more lent results than this at once is refused rather than slowed down, because
    // every way of slowing it down would be a decision this rank makes alone.
    static constexpr size_t kLentSlots = 4;

    struct LentPool {
        std::vector<Window> slots;  // grown to kLentSlots, then rotated through
        size_t              calls = 0;
    };
    std::map<at::ScalarType, LentPool> lent_;

    // Concurrent in-flight exchanges of one shape. Four covers a split q/k/v with room to spare;
    // past the bound a call waits for a slot rather than growing without limit, since every slot
    // pins a full input's worth of device memory -- and stage()'s own bound of 16 shapes is
    // therefore 16 * this many buffers.
    static constexpr size_t kMaxStagingPerShape = 4;

    // (shape, dtype) -> pool of staging buffers. unique_ptr because callers hold a Staging* across
    // the transfer, and growing the pool must not move the slots already handed out.
    std::map<std::pair<std::vector<int64_t>, at::ScalarType>, std::vector<std::unique_ptr<Staging>>> staging_;
};

