42	                                       static_cast<size_t>(op.width),
43	                                       static_cast<size_t>(op.src_slice / op.src_pitch));
44	    parms.dstPtr            = make_cudaPitchedPtr(dst,
45	                                       static_cast<size_t>(op.dst_pitch),
46	                                       static_cast<size_t>(op.width),
