90	        for (const CopyOp& op : plan.ops) {
91	            if (op.peer == p) {
92	                issue_copy(reinterpret_cast<uint8_t*>(peer_ptrs[p]) + op.dst_offset, src_bytes + op.src_offset, op, on);
93	            }
94	        }
95	    };
96	
97	    ULYSSES_CUDA_CHECK(cudaStreamWaitEvent(xfer, ready, 0));
98	    // Fault injection (see set_ce_fault): hold the payload back so the flag cannot be behind it.
99	    if (g_fault_delay_us > 0) {
100	        ULYSSES_CUDA_CHECK(cudaLaunchHostFunc(xfer, delay_payload, reinterpret_cast<void*>(g_fault_delay_us)));
101	    }
102	    for (int k = 1; k < ws; ++k) {
103	        const int peer = rank ^ k;
104	        if (peer < ws) {
105	            emit(peer, xfer);
106	        }
107	    }
108	    // XOR only enumerates every peer when ws is a power of two; sweep for any it missed.
109	    if ((ws & (ws - 1)) != 0) {
110	        for (int p = 0; p < ws; ++p) {
111	            if (p != rank && (p ^ rank) >= ws) {
112	                emit(p, xfer);
113	            }
114	        }
115	    }
116	    emit(rank, stream);
117	
118	    const Event done(cudaEventDisableTiming);
119	    ULYSSES_CUDA_CHECK(cudaEventRecord(done, xfer));
120	    // Skipping this join is the fault: the caller's stream then reaches the closing barrier, and
121	    // publishes, without waiting for the remote copies. Nothing else about the call changes.
122	    if (g_fault_delay_us == 0) {
123	        ULYSSES_CUDA_CHECK(cudaStreamWaitEvent(stream, done, 0));
124	    }
125	    // done and ready are destroyed here, in reverse declaration order, as they were by hand.
126	}
