9	// System-scope release publish / acquire load. Requires sm_70 or newer.
10	//
11	// The publish is a MAX, not a store, so a flag can never move backwards. With a window's calls
12	// ordered this cannot arise and the MAX is not load-bearing; what it buys is that a caller who
13	// breaks that ordering cannot pin a peer's flag BELOW the epoch that peer is waiting for.
14	__device__ __forceinline__ void red_release_sys_max_u64(uint64_t* addr, uint64_t v)
15	{
16	    asm volatile("red.release.sys.global.max.u64 [%0], %1;" ::"l"(addr), "l"(v) : "memory");
17	}
18	
19	__device__ __forceinline__ uint64_t ld_acquire_sys_u64(const uint64_t* addr)
20	{
21	    uint64_t v;
22	    asm volatile("ld.acquire.sys.global.u64 %0, [%1];" : "=l"(v) : "l"(addr) : "memory");
23	    return v;
24	}
25	
26	// world_size is bounded by the [1, 8] single-node limit the op layer enforces.
27	struct BarPeers {
28	    uint64_t p[8];
29	};
30	
31	__global__ void barrier_kernel(uint64_t* local, BarPeers peers, int ws, int rank)
32	{
33	    // atomicAdd rather than a plain increment, so a caller who breaks the per-window ordering
34	    // contract cannot lose an epoch outright.
35	    __shared__ uint64_t epoch;
36	    if (threadIdx.x == 0)
37	        epoch = atomicAdd(reinterpret_cast<unsigned long long*>(local + ws), 1ULL) + 1;
38	    __syncthreads();  // must precede the early-out: every launched thread has to reach it
39	
40	    int t = threadIdx.x;
41	    if (t >= ws)
42	        return;
43	    red_release_sys_max_u64(reinterpret_cast<uint64_t*>(peers.p[t]) + rank, epoch);  // peer t's flags[rank]
44	    uint64_t        v;
45	    const uint64_t* mine = local + t;  // own flags[t], written by peer t
46	    do {
47	        v = ld_acquire_sys_u64(mine);
48	    } while (v < epoch);
49	}
50	
51	}  // namespace
52	
53	void fast_barrier(cudaStream_t stream, const std::vector<uint64_t>& flag_ptrs, int rank)
54	{
55	    const int ws = static_cast<int>(flag_ptrs.size());
56	    if (ws == 1)
57	        return;
58	    BarPeers peers;
59	    for (int i = 0; i < ws; ++i)
60	        peers.p[i] = flag_ptrs[i];
61	    // A spin kernel, not stream memops (cuStreamWriteValue64/WaitValue64): the waiting memop needs
62	    // a remote-write-flush device attribute that is not always present, and measured worse under
63	    // concurrent compute. This kernel's inline PTX only requires sm_70, and it needs an SM slot
64	    // only at a kernel boundary.
65	    barrier_kernel<<<1, 32, 0, stream>>>(reinterpret_cast<uint64_t*>(flag_ptrs[rank]), peers, ws, rank);
66	    ULYSSES_CUDA_CHECK(cudaGetLastError());
67	}
68	
69	}  // namespace ulysses
